def experiment(inputs):
    import random
    seeds = inputs.get('seeds', [1, 2, 3])
    results = []
    for s in seeds:
        random.seed(s)
        results.append(random.random())
    leakage = 1.0 if len(set(results)) < len(results) else 0.0
    return {'measurements': {'cross_boundary_leakage_rate': [leakage]}}

